/** Serialized projection of the canonical Classic transcription job. */
import type { SceneTracks } from "@/timeline";
import type { CaptionLayoutSettings } from "@/subtitles/caption-layout";
import type { TranscriptionLanguage, TranscriptionWord } from "./types";
export interface TranscriptionJob {
 id: string; sceneId: string; language: TranscriptionLanguage;
 settings: CaptionLayoutSettings; defaults: Record<string, unknown>;
 sourceTracks: SceneTracks; sourceMedia: Record<string, unknown>[];
 totalDuration: number; status: "running" | "paused" | "complete";
 chunks: Record<string, TranscriptionWord[]>;
}
export type TranscriptionChange =
 | {type:"start"; sceneId:string; language:TranscriptionLanguage; settings:CaptionLayoutSettings; defaults:unknown; totalDuration:number}
 | {type:"append"; index:number; words:TranscriptionWord[]}
 | {type:"pause"|"resume"};
EOF
