p='classic/apps/web/src/core/managers/commands.ts';s=open(p).read();at=s.index('\n\t/** Shared entry for declarative UI controls.');s=s[:at]+'''
	/** Background results target their original project/scene and use the latest
	 * canonical revision. Successive sections coalesce only across untouched history. */
	editTranscription(input: { projectId: string; jobId: string; change: import("@/transcription/job").TranscriptionChange }): void {
		if (!this.canonical || this.canonical.projectId !== input.projectId || this.editor.project.getActiveOrNull()?.metadata.id !== input.projectId)
			throw new Error("The transcription project is no longer open");
		assertBatchEditable(input.projectId);
		if (this.transactionDepth !== 0) throw new Error("Finish the editor transaction before publishing transcription");
		this.synchr

